<script lang="ts">
	import Button from '$lib/components/ui/Button.svelte'; let {label,files=$bindable<File[]>([]),accept='',maxBytes=10*1024*1024,multiple=false,required=false,helper='',error='',uploadProgress,onchange}:{label:string;files?:File[];accept?:string;maxBytes?:number;multiple?:boolean;required?:boolean;helper?:string;error?:string;uploadProgress?:number;onchange?:(files:File[])=>void}=$props();let input=$state<HTMLInputElement>();let localError=$state('');const message=$derived(error||localError);const size=(n:number)=>n<1024*1024?Math.ceil(n/1024)+' KB':(n/1024/1024).toFixed(1)+' MB';function set(list:FileList|null){localError='';if(!list)return;const next=Array.from(list);const allowed=accept.split(',').map(x=>x.trim().replace('.','')).filter(Boolean);const invalid=next.find(f=>f.size>maxBytes|| (allowed.length&&!allowed.some(a=>f.name.toLowerCase().endsWith('.'+a)||f.type===a)));if(invalid){localError=invalid.size>maxBytes?`${invalid.name} exceeds the ${size(maxBytes)} limit.`:`${invalid.name} is not an accepted file type.`;return}files=multiple?[...files,...next]:[next[0]];onchange?.(files)}function remove(i:number){files=files.filter((_,index)=>index!==i);onchange?.(files)}
</script>
<div class="file-field"><span class="label">{label}{#if required}<span aria-hidden="true"> *</span>{/if}</span><button type="button" class="drop" onclick={() => input?.click()} ondragover={(e)=>e.preventDefault()} ondrop={(e)=>{e.preventDefault();set(e.dataTransfer?.files??null)}}><i class="fa-solid fa-cloud-arrow-up" aria-hidden="true"></i><strong>Drop files here or browse</strong><small>{helper || `Up to ${size(maxBytes)} each.`}</small></button><input bind:this={input} type="file" {accept} {multiple} onchange={(e)=>set(e.currentTarget.files)} /><div class="chips">{#each files as file,i}<span><i class="fa-solid fa-file" aria-hidden="true"></i>{file.name}<small>{size(file.size)}</small><Button variant="ghost" type="button" icon="fa-solid fa-xmark" ariaLabel={'Remove '+file.name} onclick={()=>remove(i)} /></span>{/each}</div>{#if uploadProgress !== undefined}<progress max="100" value={uploadProgress}>Uploading {uploadProgress}%</progress>{/if}{#if message}<p class="error" role="alert"><i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i>{message}</p>{/if}</div>
